{
  "contract": "TRYPTO",
  "closure": {
    "site_function": "take_marketing",
    "site_call": ".call",
    "functions": [
      "transfer",
      "transferFrom",
      "take_growth"
    ],
    "justification": "All public functions that can be called during the callback window and affect the exposed storage variables _ethBal and marketing_balance are included."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "take_growth"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "take_growth": 1
    }
  },
  "phases": {
    "function": "take_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "marketing_balance + growth_balance <= _ethBal + inFlight",
    "stable_formula": "marketing_balance + growth_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "marketing_balance + growth_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of marketing_balance and growth_balance does not exceed _ethBal plus any in-flight amount during the callback window."
  }
}
